[],"required":false,"variable":"action_pending"},{"type":"text-input","label":"待处理业务动作类型","default":"0","options":[],"required":false,"variable":"pending_action_type"},{"type":"text-input","label":"最近几轮用户消息（仅用于补全上下文）","default":"","options":[],"required":false,"variable":"recent_history"}]},"type":"custom","width":242,"height":227,"position":{"x":50,"y":320},"selected":false,"sourcePosition":"right","targetPosition":"left","positionAbsolute":{"x":50,"y":320}},{"id":"if_node","data":{"desc":"使用 LLM 语义判断用户意图，再进入对应业务链路","type":"question-classifier","title":"意图分类","selected":false,"query_variable_selector":["code_leave_context","context_query"],"model":{"mode":"chat","name":"qwen3.8-max","provider":"langgenius/tongyi/tongyi","completion_params":{"temperature":0.3,"enable_thinking":false}},"classes":[{"id":"emotion_record","name":"压力；难受；焦虑；抑郁；崩溃；自杀"},{"id":"stage_info","name":"我的学籍；学籍阶段；我现在什么阶段；已解锁"},{"id":"leave_records","name":"请假记录；我的请假；请假情况；请过假"},{"id":"scores","name":"成绩；分数；绩点"},{"id":"psych_profile","name":"心理画像；情绪历史；情绪记录"},{"id":"feedback_records","name":"反馈记录；售后记录；投诉记录"},{"id":"application_progress","name":"查询申请进度；申请到哪一步；当前申请状态；offer状态"},{"id":"registration_records","name":"我的报名；报名记录；报过名；报名了"},{"id":"events","name":"活动；讲座；宣讲；展会；见面会；联展"},{"id":"notifications","name":"通知；消息；提醒；未读"},{"id":"recommend","name":"推荐方案；适合我；升学路径；就业方向；移民规划"},{"id":"knowledge_help","name":"请假流程；能否请假；能请假；可以请假；条件；政策"},{"id":"leave_continue","name":"请假草稿续办：补充字段、确认、修改或取消（仅当前上下文明确存在请假草稿时）"},{"id":"leave_apply","name":"请假；请个假；病假；事假"},{"id":"feedback_create","name":"反馈；投诉；售后；报修"},{"id":"business_continue","name":"业务动作续办：补充字段、从候选选择、确认、修改或取消（仅当前存在业务动作草稿时）"},{"id":"business_action","name":"活动报名、售后提交/解决/撤回、成绩新增修改删除、客户线索录入/跟进、员工日报、就读申请新增修改撤销/推进等需要执行或消歧的业务动作"},{"id":"fallback_general","name":"普通闲聊、无法归类的其他问题或一般知识问答"}],"instruction":"请根据上下文和用户问题选择最匹配的业务类别。上下文明确存在请假草稿时，只有用户的补充、确认、修改或取消进入“请假草稿续办”；如果用户明确重新说“我要请假/我想请假/帮我请假/我需要请假”，必须进入“请假”重新发起，旧草稿字段不得沿用；没有请假草稿时，明确要请假选择“请假”；询问流程、条件、政策选择知识咨询。查询记录优先于新增，高风险情绪永远优先。不得机械按关键词判断。 当前上下文明确存在业务动作草稿时，补充、选择、确认、修改或取消优先进入“业务动作续办”。 明确要求报名、申请就读、修改或撤销申请、提交售后/日报、录入或跟进客户、新增修改删除成绩时，进入“业务动作”。","vision":{"enabled":false}},"type":"custom","width":242,"height":896,"position":{"x":350,"y":320},"selected":false,"sourcePosition":"right","targetPosition":"left","positionAbsolute":{"x":350,"y":320}},{"id":"tool_emotion","data":{"desc":"工具节点：调用已导入的自定义工具 emotion（yuejiao_api）","type":"tool","title":"调用情绪评估接口","selected":false,"tool_name":"emotion","tool_label":"提交情绪倾诉","provider_id":"1c2de193-75e4-4c78-8366-99b5f4e1ca00","provider_name":"yuejiao_api","provider_type":"api","tool_parameters":{"text":{"type":"mixed","value":"{{#sys.query#}}"},"token":{"type":"mixed","value":"{{#start_node.auth_token#}}"}},"tool_node_version":"2","tool_configurations":{},"error_strategy":"default-value","default_value":[{"key":"text","type":"string","value":"当前请求未取得业务数据：可能是当前角色无权访问，或服务暂时不可用。请直接告知用户“当前角色无权执行此操作或服务暂不可用”，不得猜测、补全或输出任何未返回的数据。"}]},"type":"custom","width":242,"height":96,"position":{"x":650,"y":40},"selected":false,"sourcePosition":"right","targetPosition":"left","positionAbsolute":{"x":650,"y":40}},{"id":"llm_emotion","data":{"desc":"","type":"llm","model":{"mode":"chat","name":"qwen3.8-max","provider":"langgenius/tongyi/tongyi","completion_params":{"temperature":0.5,"enable_thinking":false}},"title":"生成情绪安抚回复","vision":{"enabled":false},"context":{"enabled":false,"variable_selector":[]},"selected":false,"prompt_template":[{"id":"550797e0-3122-468d-99f4-a3270b3ee6d0","role":"system","text":"你是一个充满关怀的留学生管家。系统评估了用户情绪，接口返回：{{#tool_emotion.text#}}。若为高危，请表达深深关切并明确告知已经通知班主任；若为轻度压力，请温柔安慰。语气一定要温暖，不要说教。\n\n【输出规范（必须遵守）】\n1. 直接回答问题，只给结论和要点，不要输出思考过程、推理步骤、计划、工具调用说明，也不要出现“正在查询”“根据工具返回”“数据库显示”“作为 AI”这类话。\n2. 用简体中文自然分段，像同事面对面说话。禁止使用任何 markdown 符号：#、##、*、**、_、`、>、|、---。\n3. 需要罗列时用「1. 2. 3.」或「· 」，需要强调时用「」，不要加粗。\n4. 回答尽量控制在 6 行以内；用户明确要求详细时才展开，展开也分短段。\n5. 不要重复用户的问题，不要加“当然可以”“希望以上回答对你有帮助”这类客套开头结尾。\n\n【事实边界】\n涉及公司、项目、费用、政策、签证、活动、学籍和业务数据时，只能依据工具返回或公司已提供的政策、项目与业务资料回答。没有依据时直接说“公司目前暂未提供这项信息，建议由顾问进一步确认”，不得使用模型常识补全，不得推断客户符合某项资格，也不得承诺审批或办理结果。\n\n【结构化数据表格规范】\n当回答中包含两条及以上项目、活动、学生、成绩、请假、审批、报名、线索、工单或统计记录时，必须用 Markdown 表格输出。表头必须来自数据实际字段；一行动作一条记录；不得把多条记录写成连续长段落。普通说明、单条确认、追问和错误提示继续使用自然语言。"},{"id":"4ad7e0c3-7d4f-4882-b4b3-08d8783dd97f","role":"user","text":"{{#sys.query#}}"}],"memory":{"window":{"size":10,"enabled":true},"role_prefix":{"user":"","assistant":""},"query_prompt_template":"{{#sys.query#}}"}},"type":"custom","width":242,"height":88,"position":{"x":950,"y":40},"selected":false,"sourcePosition":"right","targetPosition":"left","positionAbsolute":{"x":950,"y":40}},{"id":"answer_emotion","data":{"desc":"","type":"answer","title":"回复安抚","answer":"{{#llm_emotion.text#}}","selected":false,"variables":[]},"type":"custom","width":242,"height":103,"position":{"x":1250,"y":40},"selected":false,"sourcePosition":"right","targetPosition":"left","positionAbsolute":{"x":1250,"y":40}},{"id":"tool_my_stage","data":{"type":"tool","title":"查询我的学籍阶段","desc":"工具节点：调用 my_stage（yuejiao_api）","selected":false,"provider_id":"1c2de193-75e4-4c78-8366-99b5f4e1ca00","provider_name":"yuejiao_api","provider_type":"api","tool_name":"my_stage","tool_label":"我的学籍阶段","tool_configurations":{},"tool_parameters":{"authorization":{"type":"mixed","value":"Bearer {{#start_node.auth_token#}}"}},"tool_node_version":"2","error_strategy":"default-value","default_value":[{"key":"text","type":"string","value":"当前请求未取得业务数据：可能是当前角色无权访问，或服务暂时不可用。请直接告知用户“当前角色无权执行此操作或服务暂不可用”，不得猜测、补全或输出任何未返回的数据。"}]},"type":"custom","width":242,"height":96,"position":{"x":650,"y":250},"selected":false,"sourcePosition":"right","targetPosition":"left","positionAbsolute":{"x":650,"y":250}},{"id":"llm_my_stage","data":{"desc":"","type":"llm","model":{"mode":"chat","name":"qwen3.8-max","provider":"langgenius/tongyi/tongyi","completion_params":{"temperature":0.3,"enable_thinking":false}},"title":"整理学籍阶段","vision":{"enabled":false},"context":{"enabled":false,"variable_selector":[]},"selected":false,"prompt_template":[{"role":"system","text":"接口返回当前学籍阶段和功能解锁情况：{{#tool_my_stage.text#}}。请说明当前阶段、可用的服务、尚不可用的服务和下一步该做什么。\n\n【输出规范（必须遵守）】\n1. 直接回答问题，只给结论和要点，不要输出思考过程、推理步骤、计划、工具调用说明，也不要出现“正在查询”“根据工具返回”“数据库显示”“作为 AI”这类话。\n2. 用简体中文，像顾问面对面说话。普通说明用自然段落，不要堆砌标题和粗体。\n3. 当返回多条项目、活动、学生、成绩、请假、审批、报名、线索、工单或统计记录时，必须使用 Markdown 表格，先给表头再逐行给数据，不得把多条记录挤成一段。表格列只使用工具实际返回的字段。\n4. 单条确认、追问、错误说明和普通建议使用自然语言，不必强行做表格。\n5. 回答尽量简洁；表格单元格中的文字要短，长说明放在表格后的自然段。\n6. 不要重复用户的问题，不要加“当然可以”“希望以上回答对你有帮助”这类客套开头结尾。\n\n【事实边界】\n涉及公司、项目、费用、政策、签证、活动、学籍和业务数据时，只能依据工具返回或公司已提供的政策、项目与业务资料回答。没有依据时直接说“公司目前暂未提供这项信息，建议由顾问进一步确认”，不得使用模型常识补全，不得推断客户符合某项资格，也不得承诺审批或办理结果。\n\n【结构化数据表格规范】\n当回答中包含两条及以上项目、活动、学生、成绩、请假、审批、报名、线索、工单或统计记录时，必须用 Markdown 表格输出。表头必须来自数据实际字段；一行动作一条记录；不得把多条记录写成连续长段落。普通说明、单条确认、追问和错误提示继续使用自然语言。","id":"fd0c9e3e-16c1-450e-ae1a-3df2167a63fc"},{"role":"user","text":"{{#sys.query#}}","id":"17349c93-8644-4f1e-b0cd-d2e76b45d73c"}],"memory":{"window":{"size":10,"enabled":true},"role_prefix":{"user":"","assistant":""},"query_prompt_template":"{{#sys.query#}}"}},"type":"custom","width":242,"height":88,"position":{"x":950,"y":250},"selected":false,"sourcePosition":"right","targetPosition":"left","positionAbsolute":{"x":950,"y":250}},{"id":"answer_my_stage","data":{"desc":"","type":"answer","title":"回复学籍阶段","answer":"{{#llm_my_stage.text#}}","selected":false,"variables":[]},"type":"custom","width":242,"height":103,"position":{"x":1250,"y":250},"selected":false,"sourcePosition":"right","targetPosition":"left","positionAbsolute":{"x":1250,"y":250}},{"id":"tool_my_leaves","data":{"type":"tool","title":"查询我的请假","desc":"工具节点：调用 my_leaves（yuejiao_api）","selected":false,"provider_id":"1c2de193-75e4-4c78-8366-99b5f4e1ca00","provider_name":"yuejiao_api","provider_type":"api","tool_name":"my_leaves","tool_label":"查询我的请假记录","tool_configurations":{},"tool_parameters":{"authorization":{"type":"mixed","value":"Bearer {{#start_node.auth_token#}}"}},"tool_node_version":"2","error_strategy":"default-value","default_value":[{"key":"text","type":"string","value":"当前请求未取得业务数据