0,"y":670}},{"id":"answer_course","data":{"desc":"","type":"answer","title":"回复课程","answer":"{{#llm_course.text#}}","selected":false,"variables":[]},"type":"custom","width":242,"height":103,"position":{"x":1250,"y":670},"selected":false,"sourcePosition":"right","targetPosition":"left","positionAbsolute":{"x":1250,"y":670}},{"id":"kb_node","data":{"desc":"导入后请在此节点手动勾选公司业务资料","type":"knowledge-retrieval","title":"核对公司资料","selected":false,"dataset_ids":["a7bf3a9f-872b-4941-a617-0afa5b8b61b4"],"retrieval_mode":"multiple","query_variable_selector":["sys","query"],"multiple_retrieval_config":{"top_k":3,"reranking_mode":"reranking_model","reranking_model":{"model":"qwen3-vl-rerank","provider":"langgenius/tongyi/tongyi"},"score_threshold":0.5,"reranking_enable":true}},"type":"custom","width":242,"height":118,"position":{"x":650,"y":880},"selected":false,"sourcePosition":"right","targetPosition":"left","positionAbsolute":{"x":650,"y":880}},{"id":"llm_kb","data":{"desc":"","type":"llm","model":{"mode":"chat","name":"qwen3.8-max","provider":"langgenius/tongyi/tongyi","completion_params":{"temperature":0.3,"enable_thinking":false}},"title":"生成政策回答","vision":{"enabled":false},"context":{"enabled":false,"variable_selector":[]},"selected":false,"prompt_template":[{"id":"2818ba61-8eb3-4e60-8fb6-101b003932cc","role":"system","text":"你是公司留学顾问。本次从公司业务资料中检索到的内容如下：\n{{#kb_node.result#}}\n\n请严格根据上述检索内容回答客户。资料中有明确答案时，用自然、亲切的中文直接回答，不要提资料来源。资料为空、没有相关内容，或只能靠常识猜测时，不要补全，应礼貌说明“公司目前暂未提供这项信息，建议由顾问进一步确认”，并追问客户的具体目标。不得推断签证资格、录取结果、费用或政策承诺。\n\n【结构化数据表格规范】\n当回答中包含两条及以上项目、活动、学生、成绩、请假、审批、报名、线索、工单或统计记录时，必须用 Markdown 表格输出。表头必须来自数据实际字段；一行动作一条记录；不得把多条记录写成连续长段落。普通说明、单条确认、追问和错误提示继续使用自然语言。\n\n【事实边界】\n涉及公司、项目、费用、政策、签证、活动、学籍和业务数据时，只能依据工具返回或公司已提供的政策、项目与业务资料回答。没有依据时直接说“公司目前暂未提供这项信息，建议由顾问进一步确认”，不得使用模型常识补全，不得推断客户符合某项资格，也不得承诺审批或办理结果。"},{"id":"3653843a-0436-422f-a05c-f4594893d6f0","role":"user","text":"{{#sys.query#}}"}],"memory":{"window":{"size":10,"enabled":true},"role_prefix":{"user":"","assistant":""},"query_prompt_template":"{{#sys.query#}}"}},"type":"custom","width":242,"height":88,"position":{"x":950,"y":880},"selected":false,"sourcePosition":"right","targetPosition":"left","positionAbsolute":{"x":950,"y":880}},{"id":"answer_kb","data":{"desc":"","type":"answer","title":"回复公司资料","answer":"{{#llm_kb.text#}}","selected":false,"variables":[]},"type":"custom","width":242,"height":103,"position":{"x":1250,"y":880},"selected":false,"sourcePosition":"right","targetPosition":"left","positionAbsolute":{"x":1250,"y":880}},{"id":"code_action_context","data":{"type":"code","title":"补全业务动作上下文","desc":"","selected":false,"code_language":"python3","code":"def main(query: str, action_pending: str, pending_action_type: str) -> dict:\n    state = ('当前存在待处理业务动作：' + str(pending_action_type or '')) if str(action_pending or '0') == '1' else '当前没有业务动作草稿。'\n    return {'context_query': state + '\\n用户本轮输入：' + str(query or '')}\n","variables":[{"variable":"query","value_selector":["sys","query"]},{"variable":"action_pending","value_selector":["start_node","action_pending"]},{"variable":"pending_action_type","value_selector":["start_node","pending_action_type"]}],"outputs":{"context_query":{"type":"string","children":null}},"dependencies":[]},"type":"custom","width":242,"height":120,"position":{"x":350,"y":320},"selected":false,"sourcePosition":"right","targetPosition":"left","positionAbsolute":{"x":350,"y":320}},{"id":"llm_action_extract","data":{"type":"llm","title":"LLM 提取业务动作","desc":"","selected":false,"model":{"mode":"chat","name":"qwen3.8-max","provider":"langgenius/tongyi/tongyi","completion_params":{"temperature":0.2,"enable_thinking":false}},"vision":{"enabled":false},"context":{"enabled":false,"variable_selector":[]},"prompt_template":[{"role":"system","text":"你是业务动作字段抽取器。当前待处理动作类型：{{#start_node.pending_action_type#}}。\n最近用户消息（仅补全上下文，不得覆盖本轮明确表达）：\n{{#start_node.recent_history#}}\n只输出严格 JSON，不输出解释：\n{\"action_type\":\"\", \"user_action\":\"collect|confirm|modify|cancel\", \"slots\":{...}}\n允许的 action_type：event_register。\nslots 可用字段：event_id,event_name,selection,participant_name,contact_info,\nstudent_id,student_name,course_name,score_id,score_value,\nfeedback_content,feedback_detail,ticket_id,ticket_content,customer_name,\ntarget_country,background_info,application_id,country,application_mode,\nprogram,university,remark,application_stage,note,report_content,report_date,\nlead_id,lead_status,follow_up_note,solution。\n申请动作的国家字段必须使用 country；target_country 只用于客户线索。\n规则：明确确认/提交 -> confirm；明确取消 -> cancel；明确修改 -> modify；其他 collect。\n不得补写用户没有提供的字段；无法确定的字段保持空字符串。Public visitors may only query or register for public events. Company, policy, course and fee questions must use the knowledge base.\n\n【事实边界】\n涉及公司、项目、费用、政策、签证、活动、学籍和业务数据时，只能依据工具返回或公司已提供的政策、项目与业务资料回答。没有依据时直接说“公司目前暂未提供这项信息，建议由顾问进一步确认”，不得使用模型常识补全，不得推断客户符合某项资格，也不得承诺审批或办理结果。"},{"role":"user","text":"{{#sys.query#}}"}],"memory":{"window":{"size":10,"enabled":true},"role_prefix":{"user":"","assistant":""},"query_prompt_template":"{{#sys.query#}}"}},"type":"custom","width":242,"height":88,"position":{"x":650,"y":320},"selected":false,"sourcePosition":"right","targetPosition":"left","positionAbsolute":{"x":650,"y":320}},{"id":"code_action_extract","data":{"type":"code","title":"解析业务动作字段","desc":"","selected":false,"code_language":"python3","code":"def main(raw: str) -> dict:\n    import json, re\n    text = (raw or '').strip()\n    text = re.sub(r'^```(?:json)?\\s*', '', text, flags=re.I)\n    text = re.sub(r'\\s*```$', '', text)\n    try: data = json.loads(text)\n    except Exception: data = {}\n    slots = data.get('slots') if isinstance(data.get('slots'), dict) else {}\n    clean = {str(k): v for k, v in slots.items() if v not in (None, '', [], {})}\n    action = str(data.get('user_action') or 'collect').lower()\n    if action not in ('collect','confirm','modify','cancel'): action = 'collect'\n    return {'action_type': str(data.get('action_type') or ''), 'user_action': action,\n            'slots_json': json.dumps(clean, ensure_ascii=False)}\n","variables":[{"variable":"raw","value_selector":["llm_action_extract","text"]}],"outputs":{"action_type":{"type":"string","children":null},"user_action":{"type":"string","children":null},"slots_json":{"type":"string","children":null}},"dependencies":[]},"type":"custom","width":242,"height":120,"position":{"x":950,"y":320},"selected":false,"sourcePosition":"right","targetPosition":"left","positionAbsolute":{"x":950,"y":320}},{"id":"tool_action_prepare","data":{"type":"tool","title":"准备业务动作","desc":"","selected":false,"provider_id":"1c2de193-75e4-4c78-8366-99b5f4e1ca00","provider_name":"yuejiao_api","provider_type":"api","tool_name":"prepare_business_action","tool_label":"补字段、消歧和确认","tool_configurations":{},"tool_parameters":{"token":{"type":"mixed","value":"{{#start_node.auth_token#}}"},"query":{"type":"mixed","value":"{{#sys.query#}}"},"history":{"type":"mixed","value":"{{#start_node.recent_history#}}"},"action_type":{"type":"mixed","value":"{{#code_action_extract.action_type#}}"},"user_action":{"type":"mixed","value":"{{#code_action_extract.user_action#}}"},"slots_json":{"type":"mixed","value":"{{#code_action_extract.slots_json#}}"},"visitor_key":{"type":"mixed","value":"{{#start_node.visitor_key#}}"}},"tool_node_version":"2","error_strategy":"default-value","default_value":[{"key":"text","type":"string","value":"{\"code\":500,\"msg\":\"业务服务暂不可用\",\"data\":{\"status_token\":\"STATE_ERROR\",\"message\":\"业务服务暂不可用\"}}"}]},"type":"custom","width":242,"height":96,"position":{"x":1250,"y":320},"selected":false,"sourcePosition":"right","targetPosition":"left","positionAbsolute":{"x":1250,"y":320}},{"id":"code_action_prepare","data":{"type":"code","title":"解析业务准备结果","desc":"","selected":false,"code_language":"python3","code":"def main(raw: str) -> dict:\n    import json\n    try:\n        payload = json.loads((raw or '').strip())\n        if isinstance(payload, str): payload = json.loads(payload)\n        if isinstance(payload, dict) and isinstance(payload.get('data'), dict): payload = payload['data']\n    except Exception: payload = {}\n    missing = payload.get('missing_fields') or []\n    candidates = payload.get('candidates') or []\n    lines = []\n    for item in candidates:\n        if isinstance(item, dict): lines.append(str(item.get('label') or item))\n    return {\n        'status_token': str(payload.get('status_token') or 'STATE_ERROR'),\n        'message': str(payload.get('message') or ''),\n        'preview': str(payload.get('preview') or ''),\n        'missing_text': '、'.join(str(v) for v in missing) or '无',\n        'candidates_text': '\\n'.join(lines) or '无',\n        'confirmation_token': str(payload.get('confirmation_token') or ''),\n    }\n","variables":[{"variable":"raw","value_selector":["tool_action_prepare","text"]}],"outputs":{"status_token":{"type":"string","children":null},"message":{"type":"string","children":null},"preview":{"type":"string","children":null},"missing_text":{"type":"string","children":null},"candidates_text":{"type":"string","children":null},"confirmation_token":{"type":"string","children":null}},"dependencies":[]},"type":"custom","width":242,"height":120,"position":{"x":1550,"y":320},"selected":false,"sourcePosition":"right","targetPosition":"left","positionAbsolute":{"x":1550,"y":320}},{"id":"if_action_state","data":{"type":"if-else","title":"业务动作状态分支","desc":"","selected":false,"logical_operator":"or","cases":[{"case_id":"case_action_missing","id":"case_action_missing","logical_operator":"or","conditions":[{"id":"c_action_missing","comparison_operator":"contains","value":"STATE_MISSING","varType":"string","variable_selector":["code_action_prepare","status_token"]},{"id":"c_action_ambiguous","comparison_operator":"contains","value":"STATE_AMBIGUOUS","varType":"string","variable_selector":["code_action_prepare","status_token"]}]},{"case_id":"case_action_confirm","id":"case_action_confirm","logical_operator":"and","conditions":[{"id":"c_action_confirm","comparison_operator":"contains","value":"STATE_CONFIRM","varType":"string","variable_selector":["code_action_prepare","status_token"]}]},{"case_id":"case_action_ready","id":"case_action_ready","logical_operator":"and","conditions":[{"id":"c_action_ready","comparison_operator":"contains","value":"STATE_READY","varType":"string","variable_selector":["code_action_prepare","status_token"]}]}]},"type":"custom","width":242,"height":260,"position":{"x":1850,"y":320},"selected":false,"sourcePosition":"right","targetPosition":"left","positionAbsolute":{"x":1850,"y":320}},{"id":"llm_action_ask","data":{"type":"llm","title":"业务字段追问","desc":"","selected":false,"model":{"mode":"chat","name":"qwen3.8-max","provider":"langgenius/tongyi/tongyi","completion_params":{"temperature":0.2,"enable_thinking":false}},"vision":{"enabled":false},"context":{"enabled":false,"variable_selector":[]},"prompt_template":[{"role":"system","text":"业务信息不完整或有多个候选。\n后端提示：{{#code_action_prepare.message#}}\n缺失字段：{{#code_action_prepare.missing_text#}}\n候选列表：\n{{#code_action_prepare.candidates_text#}}\n只追问缺失项；有候选时列出候选让用户选择；已明确字段不要重复追问。【输出规范】\n1. 直接给结论，不输出思考过程。\n2. 使用简体中文自然分段。多条候选、项目、活动、成绩、学生、请假、线索或工单\n   使用 Markdown 表格；单条确认、追问和错误说明使用自然语言。\n3. 不重复追问已经明确的字段。\n\n【结构化数据表格规范】\n当回答中包含两条及以上项目、活动、学生、成绩、请假、审批、报名、线索、工单或统计记录时，必须用 Markdown 表格输出。表头必须来自数据实际字段；一行动作一条记录；不得把多条记录写成连续长段落。普通说明、单条确认、追问和错误提示继续使用自然语言。\n\n【事实边界】\n涉及公司、项目、费用、政策、签证、活动、学籍和业务数据时，只能依据工具返回或公司已提供的政策、项目与业务资料回答。没有依据时直接说“公司目前暂未提供这项信息，建议由顾问进一步确认”，不得使用模型常识补全，不得推断客户符合某项资格，也不得承诺审批或办理结果。"},{"role":"user","text":"{{#sys.query#}}"}],"memory":{"window":{"size":10,"enabled":true},"role_prefix":{"user":"","assistant":""},"query_prompt_template":"{{#sys.query#}}"}},"type":"custom","width":242,"height":88,"position":{"x":2150,"y":80},"selected":false,"sourcePosition":"right","targetPosition":"left","positionAbsolute":{"x":2150,"y":80}},{"id":"llm_action_confirm","data":{"type":"llm","title":"业务动作复述确认","desc":"","selected":false,"model":{"mode":"chat","name":"qwen